xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=ZCOOL+QingKe+HuangYou&display=swap');

.xt-root {
    /* 极致温柔的淡淡微粉与复古灰 */
    --phone-body: #faf0f2;
    --phone-border: #d4bbc0;
    --phone-shadow: rgba(200, 180, 185, 0.4);
    --screen-bg: #fffcfdf2;
    --screen-border: #e6ccd2;
    --text-main: #6e5c62;
    --text-sub: #b399a1;
    --accent: #dca3b2;

    position: relative !important;
    overflow: visible !important;
    min-height: 520px;
    height: auto !important;

    background: var(--phone-body);
    border: 2px solid var(--phone-border);
    border-radius: 18px 18px 30px 30px;
    box-shadow:
        inset -3px -3px 8px rgba(0,0,0,0.03),
        inset 3px 3px 8px rgba(255,255,255,0.7),
        2px 8px 20px var(--phone-shadow);

    padding: 35px 16px 110px 16px;
    font-family: sans-serif;
}

.xt-content {
    background: var(--screen-bg);
    border: 2px solid var(--screen-border);
    border-radius: 8px;
    padding: 15px 12px;
    min-height: 340px;
    box-shadow: inset 0 0 10px rgba(220,163,178,0.15);
    position: static !important;
}

/* 听筒与小手机下方的仿真实体十字按键 */
.xt-root::before {
    content: ""; position: absolute;
    top: 14px; left: 50%; transform: translateX(-50%);
    width: 48px; height: 5px; background: var(--phone-border);
    border-radius: 6px; box-shadow: inset 0 2px 3px rgba(0,0,0,0.1);
}
.xt-root::after {
    content: ""; position: absolute;
    bottom: 25px; left: 50%; transform: translateX(-50%);
    width: 45px; height: 45px; background: #fdf5f7;
    border-radius: 50%; border: 1px solid #efe0e3;
    box-shadow: inset -2px -2px 5px rgba(0,0,0,0.03), 0 2px 5px rgba(0,0,0,0.08);
}

/* ================= 魔法双键互换核心 ================= */
.xt-content::before {
    position: absolute; bottom: 32px;
    width: 75px; height: 32px; background: var(--accent); color: #fff;
    border-radius: 6px; display: flex; align-items: center; justify-content: center;
    font-size: 11px; font-weight: bold; letter-spacing: 1px;
    box-shadow: inset 1px 1px 3px rgba(255,255,255,0.3), 0 2px 5px var(--phone-shadow);
    z-index: 10; transition: all 0.2s ease;
}

.xt-action-1 {
    position: absolute; bottom: 32px;
    width: 75px; height: 32px; background: #fdf5f7; color: var(--text-sub);
    border-radius: 6px; border: 1px solid #efe0e3;
    display: flex; align-items: center; justify-content: center;
    font-size: 11px; font-weight: bold; letter-spacing: 1px;
    box-shadow: inset -1px -1px 3px rgba(0,0,0,0.02), 0 2px 5px rgba(0,0,0,0.06);
    z-index: 10; cursor: pointer; transition: all 0.2s ease;
}

.xt-content::before { content: "常规信号"; left: 14%; }
.xt-action-1 { right: 14%; }
.xt-action-1::after { content: "深度探秘"; }
#xt-t1:checked ~ .xt-content::before { content: "深度探秘"; left: auto; right: 14%; }
#xt-t1:checked ~ .xt-content .xt-action-1 { left: 14%; right: auto; }
#xt-t1:checked ~ .xt-content .xt-action-1::after { content: "常规信号"; }

/* ================= 屏幕显隐控速 (兼容三轨跑马灯) ================= */
.xt-section, .xt-marquee { display: none !important; opacity: 0; }

.xt-action-1 + .xt-section,
.xt-action-1 + .xt-section + .xt-section,
.xt-action-1 + .xt-section + .xt-section + .xt-section {
    display: block !important;
    animation: screenFade 0.4s ease forwards;
}

#xt-t1:checked ~ .xt-content .xt-section,
#xt-t1:checked ~ .xt-content .xt-marquee {
    display: block !important;
    animation: screenFade 0.4s ease forwards;
}

#xt-t1:checked ~ .xt-content .xt-action-1 + .xt-section,
#xt-t1:checked ~ .xt-content .xt-action-1 + .xt-section + .xt-section,
#xt-t1:checked ~ .xt-content .xt-action-1 + .xt-section + .xt-section + .xt-section {
    display: none !important;
}

@keyframes screenFade { 0% { opacity: 0; filter: blur(3px); } 100% { opacity: 1; filter: none; } }

/* ================= 屏幕内排版 ================= */
.xt-header { border-bottom: 1px dashed var(--screen-border); padding-bottom: 10px; margin-bottom: 15px; }
.xt-avatar { border: 2px solid var(--accent); }
.xt-name { color: var(--text-main); font-weight: bold; }

.xt-section-title {
    color: #fff; background: var(--accent);
    padding: 2px 8px; border-radius: 4px;
    font-size: 11px; margin-bottom: 8px; margin-top: 12px;
}
.xt-section:nth-of-type(1) .xt-section-title,
.xt-section:nth-of-type(4) .xt-section-title { margin-top: 0; }

.xt-section-body {
    background: transparent !important; border: none !important;
    color: var(--text-sub); font-size: 13px; line-height: 1.6;
    font-weight: bold; padding-left: 0; margin-bottom: 8px;
}

.xt-section:nth-of-type(3) .xt-section-body,
.xt-section:nth-of-type(5) .xt-section-body {
    color: var(--text-main); font-style: italic;
    background: rgba(220,163,178,0.1) !important;
    padding: 8px 10px; border-radius: 6px;
}

/* ================= 魔改后的物理学跑马灯 ================= */
.xt-marquee {
    width: 100%; overflow: hidden; white-space: nowrap;
    margin-top: 5px;
}

/* 【修复重点1】使用最直接的兄弟选择器，强制锁定跟在区块后面的第一跳轨道，必定会画出标题！ */
.xt-section + .xt-marquee { margin-top: 12px; }
.xt-section + .xt-marquee::before {
    content: "外部弹幕"; display: block;
    color: #fff; background: var(--accent);
    padding: 2px 8px; border-radius: 4px;
    font-size: 11px; margin-bottom: 8px; width: max-content;
}

/* 弹幕变为小气泡外观 */
.xt-marquee-inner {
    display: inline-block;
    background: rgba(220,163,178,0.15) !important;
    color: #db7a95; /* 颜色调深，确保白底能看到字 */
    padding: 4px 12px; border-radius: 12px;
    font-weight: bold; font-size: 12px; letter-spacing: 0.5px;
    /* 循环动画 */
    animation: danmakuRoll linear infinite;
}

/* 【修复重点2】改用固定的屏幕像素飞行距离！绝不会再出现乱闪和消失 */
@keyframes danmakuRoll {
    0% { transform: translateX(350px); } /* 从屏幕绝对右外侧起跑 */
    100% { transform: translateX(-800px); } /* 冲向屏幕绝对左侧，保证长句子也能飞完 */
}

/* 第一轨：慢速幽行 */
.xt-marquee:nth-last-of-type(3) .xt-marquee-inner { animation-duration: 14s; }

/* 第二轨：极速掠过，飞过时如同流星 */
.xt-marquee:nth-last-of-type(2) .xt-marquee-inner { animation-duration: 10s; animation-delay: 2.5s; }

/* 第三轨：中速平稳飞行 */
.xt-marquee:nth-last-of-type(1) .xt-marquee-inner { animation-duration: 12s; animation-delay: 5s; }

.xt-footer { display: none; }

xinshengLayout:
# 纯爱复古微粉小手机 (实体双按键版)
@header charImage charName .fadeInDown
@toggle 1

# ==== 页面 1：常规状态 (默认显示) ====
@section 当前心情
  mood
@section 此刻正在
  action
@section 纯爱频道
  voice

# ==== 页面 2：深度探秘 (点击后显示) ====
@section 随身羁绊
  inventory
@section 生理档案
  genitals
@marquee danmaku1
@marquee danmaku2
@marquee danmaku3

xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@300;400;500;700&display=swap');

/* ══════════════════════
   ROOT
══════════════════════ */
.xt-root {
  --xt-bg:         #f0eefe;
  --xt-text:       #3a2858;
  --xt-text-sub:   #7868a8;
  --xt-text-muted: #b0a8d0;
  --xt-accent:     #7a9ae0;
  --xt-accent-bg:  rgba(172,199,255,0.15);
  --xt-border:     #c8c0e8;
  --xt-radius:     18px;
  --xt-radius-sm:  11px;
  --xt-font:       'Noto Sans SC','PingFang SC','Hiragino Sans GB',sans-serif;
  --xt-anim-duration: 0.28s;
  --pink:          #9080d0;
  --pink-bg:       #f4f0ff;
  --pink-border:   #c8b8f0;
  --pink-text:     #5a3898;
  background: var(--xt-bg);
  padding: 0;
  font-size: 13px;
  line-height: 1.5;
}
.xt-content { padding: 14px 13px 14px; }

/* ══════════════════════
   CARD 通用
══════════════════════ */
.xt-card {
  background: #fff !important;
  border: 1.5px solid #dcd4f4 !important;
  border-radius: 16px !important;
  padding: 0 !important;
  margin-bottom: 10px !important;
  box-shadow: 0 2px 12px rgba(172,199,255,0.30) !important;
  overflow: hidden !important;
}
.xt-card:hover { box-shadow: 0 4px 18px rgba(122,154,224,0.22) !important; transform: none !important; }
.xt-card-title {
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #b0a8d0 !important;
  letter-spacing: 1.2px !important;
  text-transform: uppercase !important;
  padding: 11px 14px 2px !important;
  margin: 0 !important;
  display: block !important;
}

/* ══════════════════════
   最近搜索区
   设计：带标题的独立白卡
   四行搜索词 + 展开心声
══════════════════════ */

/* 四个搜索词共同外包一个白卡效果
   用 search1 第一行的 ::before 做卡片标题 */
.xt-text-search1 {
  margin-top: 0 !important;
  border-radius: 16px 16px 0 0 !important;
  border-bottom: 1px solid #f2eefa !important;
  padding-top: 10px !important;
}
.xt-text-search1::before {
  content: "🔍  最近搜索" !important;
  display: block !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #b0a8d0 !important;
  letter-spacing: 1.2px !important;
  text-transform: uppercase !important;
  margin-bottom: 8px !important;
  padding: 0 !important;
}

/* 四个搜索词的共同样式 */
.xt-text-search1,
.xt-text-search2,
.xt-text-search3,
.xt-text-search4 {
  display: block !important;
  background: #ffffff !important;
  border-left: 1.5px solid #dcd4f4 !important;
  border-right: 1.5px solid #dcd4f4 !important;
  border-top: none !important;
  border-bottom: 1px solid #f2eefa !important;
  border-radius: 0 !important;
  padding: 11px 40px 11px 16px !important;
  margin: 0 !important;
  font-size: 13.5px !important;
  font-weight: 400 !important;
  color: #3a2858 !important;
  font-style: normal !important;
  cursor: pointer !important;
  position: relative !important;
  transition: background 0.15s !important;
}
/* 左侧搜索图标 */
.xt-text-search1::after,
.xt-text-search2::after,
.xt-text-search3::after,
.xt-text-search4::after {
  content: "›" !important;
  position: absolute !important;
  right: 15px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  font-size: 20px !important;
  color: #b8b0d8 !important;
  line-height: 1 !important;
  transition: color 0.15s, transform 0.2s !important;
  font-style: normal !important;
}
/* 最后一行圆角收尾（无心声展开时） */
.xt-text-search4 {
  border-radius: 0 0 16px 16px !important;
  border-bottom: 1.5px solid #dcd4f4 !important;
  margin-bottom: 10px !important;
}
/* 展开时最后一行取消圆角，由OS气泡接管 */
#xt-t4:checked ~ .xt-content .xt-text-search4 {
  border-radius: 0 !important;
  border-bottom: 1px solid #f2eefa !important;
}

/* 选中状态高亮 */
#xt-t1:checked ~ .xt-content .xt-text-search1 { background: #ede8ff !important; color: #1e1040 !important; }
#xt-t2:checked ~ .xt-content .xt-text-search2 { background: #ede8ff !important; color: #1e1040 !important; }
#xt-t3:checked ~ .xt-content .xt-text-search3 { background: #ede8ff !important; color: #1e1040 !important; }
#xt-t4:checked ~ .xt-content .xt-text-search4 { background: #ede8ff !important; color: #1e1040 !important; }
#xt-t1:checked ~ .xt-content .xt-text-search1::after { color: #7a9ae0 !important; transform: translateY(-50%) rotate(90deg) !important; }
#xt-t2:checked ~ .xt-content .xt-text-search2::after { color: #7a9ae0 !important; transform: translateY(-50%) rotate(90deg) !important; }
#xt-t3:checked ~ .xt-content .xt-text-search3::after { color: #7a9ae0 !important; transform: translateY(-50%) rotate(90deg) !important; }
#xt-t4:checked ~ .xt-content .xt-text-search4::after { color: #7a9ae0 !important; transform: translateY(-50%) rotate(90deg) !important; }

/* 搜索心声气泡 */
.xt-text-search1Os,
.xt-text-search2Os,
.xt-text-search3Os,
.xt-text-search4Os {
  display: block !important;
  max-height: 0 !important;
  overflow: hidden !important;
  background: #f5f2ff !important;
  border-left: 1.5px solid #dcd4f4 !important;
  border-right: 1.5px solid #dcd4f4 !important;
  border-top: none !important;
  border-bottom: none !important;
  border-radius: 0 !important;
  padding: 0 16px !important;
  margin: 0 !important;
  font-size: 12.5px !important;
  color: #5850a0 !important;
  font-style: italic !important;
  line-height: 1.75 !important;
  transition: max-height 0.3s ease, padding 0.22s ease !important;
}
/* search4的Os展开后需要有底部圆角 */
.xt-text-search4Os {
  border-radius: 0 0 16px 16px !important;
  border-bottom: 1.5px solid #dcd4f4 !important;
  margin-bottom: 10px !important;
}
#xt-t1:checked ~ .xt-content .xt-text-search1Os { max-height: 100px !important; padding: 10px 16px 12px !important; }
#xt-t2:checked ~ .xt-content .xt-text-search2Os { max-height: 100px !important; padding: 10px 16px 12px !important; }
#xt-t3:checked ~ .xt-content .xt-text-search3Os { max-height: 100px !important; padding: 10px 16px 12px !important; }
#xt-t4:checked ~ .xt-content .xt-text-search4Os { max-height: 100px !important; padding: 10px 16px 12px !important; }

/* 透明按钮覆盖搜索词行 */
.xt-action-1,.xt-action-2,.xt-action-3,.xt-action-4 {
  display: block !important;
  width: 100% !important;
  height: 44px !important;
  margin: -44px 0 0 0 !important;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  cursor: pointer !important;
  position: relative !important;
  z-index: 5 !important;
  opacity: 0 !important;
  font-size: 0 !important;
}
.xt-action-1::after,.xt-action-2::after,
.xt-action-3::after,.xt-action-4::after { content: "" !important; }

/* ══════════════════════
   ROW 两列
══════════════════════ */
.xt-row { gap: 9px !important; margin-bottom: 10px !important; align-items: stretch !important; }
.xt-row > * { margin-bottom: 0 !important; }

/* ── 动物塑 */
.xt-text-animalType {
  display: block !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #7a9ae0 !important;
  letter-spacing: 0.8px !important;
  font-style: normal !important;
  padding: 5px 13px 2px !important;
  background: transparent !important;
  border: none !important;
  text-transform: uppercase !important;
}
