}
@keyframes gift-sparkle-2{
  0%,100%{ opacity: 0; }
  40%{ opacity: 0.8; }
  80%{ opacity: 0; }
}
@keyframes gift-sparkle-3{
  0%,100%{ opacity: 0; }
  30%{ opacity: 1; }
  70%{ opacity: 0.3; }
}
.gift-ig-container.msg-gift-card{
